(function(root){
 'use strict';
 const characters={nyx:{name:'Nyx',title:'Esprit lunaire',power:'Impulsion',icon:'↗',speed:180,cooldown:7,cost:4,description:'Un élan vif pour échapper aux ombres. Équilibré et agile.',condition:'Disponible dès le départ'},mira:{name:'Mira',title:'Aile des constellations',power:'Attraction',icon:'✧',speed:170,cooldown:10,cost:5,description:'Attire les lueurs pendant 4 secondes. Perd plus de lumière en cas de capture.',condition:'Rallumer 12 sanctuaires'},orion:{name:'Orion',title:'Gardien de cristal',power:'Bouclier',icon:'⬡',speed:145,cooldown:12,cost:5,description:'Un bouclier de 4 secondes protège des ombres. Plus lent, plus serein.',condition:'Remporter 3 expéditions'},umbra:{name:'Umbra',title:'Enfant de l’éclipse',power:'Traversée',icon:'☽',speed:185,cooldown:11,cost:7,description:'Traverse les ombres pendant 3 secondes. Son pouvoir consomme davantage.',condition:'Gagner sans aucune capture'}};
 const fresh=()=>({version:1,cj:0,activeSeconds:0,selected:'nyx',skin:'aurore',owned:['aurore'],stats:{runs:0,wins:0,shrines:0,collected:0,absorbed:0,powers:0,flawless:0,fast:0,close:0,miraWins:0},sound:false});
 function normalize(raw){const p=fresh();if(!raw||typeof raw!=='object')return p;for(const k of Object.keys(p.stats)){const v=Number(raw.stats?.[k]);p.stats[k]=Number.isFinite(v)?Math.max(0,Math.floor(v)):0;}p.cj=Number.isFinite(raw.cj)?Math.max(0,Math.floor(raw.cj)):0;p.activeSeconds=Number.isFinite(raw.activeSeconds)?Math.max(0,raw.activeSeconds)%600:0;p.owned=['aurore',...['or','rose','givre'].filter(x=>raw.owned?.includes(x))];p.skin=p.owned.includes(raw.skin)?raw.skin:'aurore';p.selected=characters[raw.selected]?raw.selected:'nyx';p.sound=raw.sound===true;if(!unlocked(p,p.selected))p.selected='nyx';return p;}
 function unlocked(p,id){return id==='nyx'||id==='mira'&&p.stats.shrines>=12||id==='orion'&&p.stats.wins>=3||id==='umbra'&&p.stats.flawless>=1;}
 function creditTime(p,seconds){p.activeSeconds+=Math.max(0,seconds);const n=Math.floor(p.activeSeconds/600);p.activeSeconds-=n*600;p.cj+=n;return n;}
 const challenges=[['Premier éclat','Récolter 100 lueurs','collected',100],['Passeuse de lumière','Rallumer 3 sanctuaires','shrines',3],['Un ciel nouveau','Réussir une expédition','wins',1],['Mira s’éveille','Rallumer 12 sanctuaires','shrines',12],['Le gardien répond','Réussir 3 expéditions','wins',3],['Sans une égratignure','Gagner sans capture · débloque Umbra','flawless',1],['Avant l’éclipse','Gagner en moins de 4 minutes','fast',1],['Dernière étincelle','Gagner avec une seule vie','close',1],['Danse des ombres','Absorber 20 petites ombres','absorbed',20],['Sous les ailes de Mira','Gagner une expédition avec Mira','miraWins',1]];
 const skins={aurore:{name:'Aurore',color:'#7de6ff',price:0,description:'Le souffle bleu des premières nuits.'},or:{name:'Poussière d’or',color:'#ffd987',price:2,description:'Une traînée de petites étoiles dorées.'},rose:{name:'Brume astrale',color:'#eda5e9',price:3,description:'Une lumière rose venue des nébuleuses.'},givre:{name:'Givre lunaire',color:'#c2fff0',price:3,description:'Des éclats givrés au sillage de ta créature.'}};
 function purchase(p,id){const item=skins[id];if(!item||p.owned.includes(id)||p.cj<item.price)return false;p.cj-=item.price;p.owned.push(id);p.skin=id;return true;}
 const balance={maxLight:400,offeringDuration:4,finalSeconds:60};
 function offeringCost(lit){return [80,160,240][Math.min(2,Math.max(0,lit))];}
 function lightGain(mass,amount){return Math.min(balance.maxLight,mass+amount/(1+Math.max(0,mass-160)/200));}
 const api={characters,fresh,normalize,unlocked,creditTime,challenges,skins,purchase,balance,offeringCost,lightGain};root.LueurCore=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
